import{_ as a,o as n,c as s,a5 as t}from"./chunks/framework.CslsFoWx.js";const r="/VendoraSystem-docs/captures/2026-10-29-encaissement-android/01-ouverture-session.png",o="/VendoraSystem-docs/captures/2026-10-29-encaissement-android/02-panier.png",i="/VendoraSystem-docs/captures/2026-10-29-encaissement-android/03-feuille-paiement-rendu.png",c="/VendoraSystem-docs/captures/2026-10-29-encaissement-android/04-confirmation-vente.png",d="/VendoraSystem-docs/captures/2026-10-29-encaissement-android/05-historique-ventes.png",_=JSON.parse('{"title":"Encaissement Android — captures du 2026-10-29","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-10-29-encaissement-android.md","filePath":"generated/preuves/2026-10-29-encaissement-android.md","lastUpdated":null}'),u={name:"preuves/2026-10-29-encaissement-android.md"};function l(p,e,g,m,f,h){return n(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="encaissement-android-—-captures-du-2026-10-29" tabindex="-1">Encaissement Android — captures du 2026-10-29 <a class="header-anchor" href="#encaissement-android-—-captures-du-2026-10-29" aria-label="Permalink to &quot;Encaissement Android — captures du 2026-10-29&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-10-29-encaissement-android</code> · 5 image(s) · 0 trace(s)</p><div><p>Parcours complet d&#39;encaissement sur l&#39;émulateur <code>Medium_Phone_API_36.1</code> (appairé au serveur local <code>10.0.2.2:8080</code>, rôle REGISTER, catalogue synchronisé). Toutes les valeurs sont calculées par le moteur partagé (<code>:shared</code>) : l&#39;UI n&#39;affiche que les résultats de <code>CashSessionManager</code>, <code>PaymentCalculator</code> et <code>CheckoutService</code>.</p><h2 id="_01-ouverture-session-png" tabindex="-1">01-ouverture-session.png <a class="header-anchor" href="#_01-ouverture-session-png" aria-label="Permalink to &quot;01-ouverture-session.png&quot;">​</a></h2><p>Dialogue « Ouvrir la session », proposé automatiquement à l&#39;entrée de l&#39;écran caisse quand aucune session n&#39;est OPEN (RG-CASH-04). Le bandeau d&#39;en-tête affiche « Aucune session de caisse » en rouge. Fond de caisse saisi en devise majeure : <strong>100</strong> TND (converti en 100 000 millimes côté moteur, RG-CASH-03).</p><h2 id="_02-panier-png" tabindex="-1">02-panier.png <a class="header-anchor" href="#_02-panier-png" aria-label="Permalink to &quot;02-panier.png&quot;">​</a></h2><p>Après ouverture : le bandeau discret affiche <strong>« Session #1 »</strong>. Le produit « Eau 1,5L » (1,200 TND) a été ajouté au panier d&#39;un tap ; le panneau du bas montre la ligne, le TOTAL (1,200 TND) et le bouton <strong>« Encaisser 1,200 TND »</strong>.</p><h2 id="_03-feuille-paiement-rendu-png" tabindex="-1">03-feuille-paiement-rendu.png <a class="header-anchor" href="#_03-feuille-paiement-rendu-png" aria-label="Permalink to &quot;03-feuille-paiement-rendu.png&quot;">​</a></h2><p>Feuille de paiement ouverte via « Encaisser » : total dû 1,200 TND, boutons rapides espèces (Exact, 5, 10, 20, 50), champs espèces/carte (paiement mixte possible, carte = confirmation manuelle en v1). Espèces saisies : <strong>2.000</strong> → <strong>RENDU 0,800 TND</strong> calculé en direct par <code>PaymentCalculator</code> (la vérité reste le <code>CheckoutOutcome</code> au moment de la confirmation). Le bouton « Encaisser » n&#39;est actif que si le ticket est soldé.</p><h2 id="_04-confirmation-vente-png" tabindex="-1">04-confirmation-vente.png <a class="header-anchor" href="#_04-confirmation-vente-png" aria-label="Permalink to &quot;04-confirmation-vente.png&quot;">​</a></h2><p>Confirmation après <code>CheckoutService.checkout(...)</code> : <strong>« Vente encaissée ✓ »</strong>, numéro de ticket local <strong>1498cd-1-1</strong> (<code>&lt;devicePrefix 6&gt;-&lt;sessionNo&gt;-&lt;seq&gt;</code>, RG-SALE-40) et <strong>rendu à remettre 0,800 TND</strong>. Le panier est vidé et le push de l&#39;outbox vers le serveur est déclenché en arrière-plan (la vente reste locale si le push échoue — l&#39;en-tête afficherait alors « N évt. à synchroniser »).</p><h2 id="_05-historique-ventes-png" tabindex="-1">05-historique-ventes.png <a class="header-anchor" href="#_05-historique-ventes-png" aria-label="Permalink to &quot;05-historique-ventes.png&quot;">​</a></h2><p>Menu ⋮ → « Ventes de la session » : liste des ventes de la session OPEN via <code>SalesHistoryRepository</code> — numéro local (1498cd-1-1), heure (01:33) et total (1,200 TND), la plus récente d&#39;abord.</p></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-encaissement-android/01-ouverture-session.png" target="_blank"><img src="'+r+'" alt="01-ouverture-session.png" loading="lazy"></a><figcaption>01-ouverture-session.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-encaissement-android/02-panier.png" target="_blank"><img src="'+o+'" alt="02-panier.png" loading="lazy"></a><figcaption>02-panier.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-encaissement-android/03-feuille-paiement-rendu.png" target="_blank"><img src="'+i+'" alt="03-feuille-paiement-rendu.png" loading="lazy"></a><figcaption>03-feuille-paiement-rendu.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-encaissement-android/04-confirmation-vente.png" target="_blank"><img src="'+c+'" alt="04-confirmation-vente.png" loading="lazy"></a><figcaption>04-confirmation-vente.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-encaissement-android/05-historique-ventes.png" target="_blank"><img src="'+d+'" alt="05-historique-ventes.png" loading="lazy"></a><figcaption>05-historique-ventes.png</figcaption></figure></div>',5)])])}const b